<?php
declare(strict_types=1);
require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/schema.php';
$remote=(string)($_SERVER['REMOTE_ADDR']??'');$local=in_array($remote,['127.0.0.1','::1'],true);if(!$local){nxt_status_page(403,'Local setup only','Open this terminal through localhost on the computer hosting Digimon NXT.');}
$messages=[];$error='';$cfg=(array)pv_config('db',[]);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{pv_require_csrf();$host=(string)($cfg['host']??'127.0.0.1');$user=(string)($cfg['user']??'root');$pass=(string)($cfg['pass']??'');$port=(int)($cfg['port']??3306);$dbName=(string)($cfg['name']??'digimon_nxt');$server=@new mysqli($host,$user,$pass,'',$port);if($server->connect_errno)throw new RuntimeException('Could not connect to MariaDB/MySQL: '.$server->connect_error);$server->set_charset('utf8mb4');
   if(isset($_POST['fresh'])){if(!$server->query('DROP DATABASE IF EXISTS `'.str_replace('`','',$dbName).'`'))throw new RuntimeException($server->error);$messages[]='Removed any previous Digimon NXT database.';}
   if(!$server->query('CREATE DATABASE IF NOT EXISTS `'.str_replace('`','',$dbName).'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci'))throw new RuntimeException($server->error);if(!$server->select_db($dbName))throw new RuntimeException($server->error);$GLOBALS['mysql_connection']=$server;$changes=dn_apply_schema_migrations($server);$messages=array_merge($messages,$changes);$messages[]='Digimon NXT database is ready.';
 }catch(Throwable $e){$error=$e->getMessage();pv_log('Setup error: '.$error);}
}
$ready=false;$count=0;$tableCount=0;try{$db=pv_db();$ready=pv_table_exists('digimon_species')&&pv_table_exists('members');if($ready&&($r=$db->query('SELECT COUNT(*) c FROM digimon_species')))$count=(int)$r->fetch_assoc()['c'];if($ready&&($r=$db->query('SELECT COUNT(*) c FROM information_schema.tables WHERE table_schema=DATABASE()')))$tableCount=(int)$r->fetch_assoc()['c'];}catch(Throwable){}
pv_page_start('Setup','',false);
?><main class="nxt-document"><section class="pv-card nxt-document-panel"><span class="pv-eyebrow">LOCAL INSTALLATION UTILITY</span><h1>Digimon NXT Setup</h1><p class="pv-subtle">This creates the clean Digimon NXT schema and synchronizes the bundled species catalog and 1,000 rival tamers. Existing saves are preserved by Create / Repair Schema. Fresh Rebuild intentionally deletes only the <code>digimon_nxt</code> database.</p><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><?php foreach($messages as $m):?><div class="pv-flash success"><?=pv_h($m)?></div><?php endforeach;?><div class="dn-stat-strip nxt-setup-stats"><div><span>Database</span><strong><?=$ready?'READY':'NOT READY'?></strong></div><div><span>Species</span><strong><?=$ready?$count:'—'?></strong></div><div><span>Tables</span><strong><?=$ready?$tableCount:'—'?></strong></div><div><span>Target DB</span><strong style="font-size:14px">digimon_nxt</strong></div><div><span>Version</span><strong style="font-size:14px"><?=pv_h((string)pv_config('asset_version'))?></strong></div></div><form method="post" style="margin-top:18px"><?=pv_csrf_field()?><div class="pv-actions"><button class="pv-button" name="upgrade" value="1">Create / Repair Schema</button><button class="pv-button pv-button-secondary" name="fresh" value="1" onclick="return confirm('Delete and rebuild the digimon_nxt database?')">Fresh Rebuild</button><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('index.php'))?>">Open Game</a></div></form><?php if($ready):?><h2>Keep your rivals active</h2><p>Open <code>tools/install_tamer_service_windows.bat</code> from the extracted download once. Its game path must match this installed folder: <code><?=pv_h(__DIR__)?></code>. The background task runs tamers with no players online and starts again when Windows starts.</p><p>After installation, Tamer Activity shows <strong>Background worker connected</strong>. Keep MySQL running; the worker reconnects automatically after a database restart.</p><?php endif;?></section></main><?php pv_page_end();?>
